-- Athena saved query (Product_B2C_Intl)
-- ID: 5d27bb9f-ed36-4ef6-bee6-d04e510ddeff
-- Name: Price Variant AB - Closed loop funnel - Cursor - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH params AS ( SELECT TIMESTAMP '2026-04-10 18:30:00' AS t_start, TIMESTAMP '2026-04-11 18:30:00' AS t_end ), /* SRP tuple events (keep __time for sequencing) */ srp_events AS ( SELECT s.mri_session_id, s.route_id, s.__time AS srp_time, s.os, s.channel, s.user_type, CASE WHEN contains(channel_exp_info, 'priceVariantAB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'priceVariantAB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'priceVariantAB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'priceVariantAB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'priceVariantAB:V4') THEN 'V4' ELSE 'others' END AS exp_Variant, date_format(at_timezone(s.__time, 'Asia/Kolkata'), '%Y-%b') AS month_period FROM user_interaction.search_route_details s CROSS JOIN params p WHERE s.__time >= p.t_start AND s.__time < p.t_end AND s.country = 'IND' AND s.channel_exp_info IS NOT NULL AND s.channel IN ('MOBILE_WEB', 'WEB_DIRECT') AND s.akamai_bot IS NULL AND s.tp_channel = 'INVALID' ), /* SL lands (multiple per session/route allowed) */ sl_events AS ( SELECT s.mri_session_id, s.route_id, s.__time AS sl_time FROM user_interaction.seat_layout_details s CROSS JOIN params p WHERE s.__time >= p.t_start AND s.__time < p.t_end AND s.country = 'IND' ), /* Each SL land becomes an "instance" linked to the latest SRP tuple before it */ sl_instances AS ( SELECT sl.mri_session_id, sl.route_id, sl.sl_time, srp.srp_time, srp.os, srp.channel, srp.user_type, srp.exp_Variant, srp.month_period FROM sl_events sl JOIN ( SELECT sl.mri_session_id, sl.route_id, sl.sl_time, MAX(srp.srp_time) AS srp_time FROM sl_events sl JOIN srp_events srp ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id AND srp.srp_time < sl.sl_time GROUP BY 1,2,3 ) link ON link.mri_session_id = sl.mri_session_id AND link.route_id = sl.route_id AND link.sl_time = sl.sl_time JOIN srp_events srp ON srp.mri_session_id = link.mri_session_id AND srp.route_id = link.route_id AND srp.srp_time = link.srp_time ), /* UI events filtered */ ui_events AS ( SELECT u.mri_session_id, u.__time AS ui_time, u.event_name, u.event_value FROM user_interaction.ui_ux_events u CROSS JOIN params p WHERE u.__time >= p.t_start AND u.__time < p.t_end AND u.event_group = 'ab_exp_srp_price' ), /* Assign each UI event to the nearest SL land (within buffer) in same session. Tune the buffer if needed (e.g., -1s to +6s). */ ui_assigned_to_sl AS ( SELECT x.mri_session_id, x.route_id, x.sl_time, x.ui_time, x.event_name, x.event_value FROM ( SELECT sl.mri_session_id, sl.route_id, sl.sl_time, u.ui_time, u.event_name, u.event_value, row_number() OVER ( PARTITION BY sl.mri_session_id, u.ui_time, u.event_name, u.event_value ORDER BY abs(date_diff('millisecond', u.ui_time, sl.sl_time)) ASC ) AS rn FROM sl_events sl JOIN ui_events u ON u.mri_session_id = sl.mri_session_id AND u.ui_time BETWEEN sl.sl_time - INTERVAL '1' SECOND AND sl.sl_time + INTERVAL '6' SECOND ) x WHERE x.rn = 1 ), /* Instance-level UI flags derived from the assigned UI events */ ui_flags_per_sl AS ( SELECT i.mri_session_id, i.route_id, i.sl_time, MAX(CASE WHEN a.event_name = 'SL loaded' THEN 1 ELSE 0 END) AS sl_Land, MAX(CASE WHEN a.event_value = 'Yes' THEN 1 ELSE 0 END) AS Price_range FROM sl_instances i LEFT JOIN ui_assigned_to_sl a ON a.mri_session_id = i.mri_session_id AND a.sl_time = i.sl_time GROUP BY 1,2,3 ), /* next SRP load after SL land (session-level) */ next_srp_after_sl AS ( SELECT i.mri_session_id, i.route_id, i.sl_time, MIN(s.srp_time) AS next_srp_time FROM sl_instances i JOIN srp_events s ON s.mri_session_id = i.mri_session_id AND s.srp_time > i.sl_time GROUP BY 1,2,3 ), custinfo_after_sl AS ( SELECT i.mri_session_id, i.route_id, i.sl_time, MIN(c.__time) AS custinfo_time FROM sl_instances i JOIN user_interaction.cust_info_details c ON c.mri_session_id = i.mri_session_id AND c.route_id = i.route_id CROSS JOIN params p WHERE c.__time >= p.t_start AND c.__time < p.t_end AND c.country = 'IND' AND c.__time > i.sl_time GROUP BY 1,2,3 ), payment_after_sl AS ( SELECT i.mri_session_id, i.route_id, i.sl_time, MIN(o.__time) AS payment_time FROM sl_instances i JOIN user_interaction.order_info_details o ON o.mri_session_id = i.mri_session_id AND o.route_id = i.route_id CROSS JOIN params p WHERE o.__time >= p.t_start AND o.__time < p.t_end AND o.country = 'IND' AND o.__time > i.sl_time GROUP BY 1,2,3 ), confirm_after_sl AS ( SELECT i.mri_session_id, i.route_id, i.sl_time, MIN(c.__time) AS confirm_time, COUNT(DISTINCT c.tin) AS tin_count FROM sl_instances i JOIN user_interaction.confirm_order_details c ON c.mri_session_id = i.mri_session_id AND c.route_id = i.route_id CROSS JOIN params p WHERE c.__time >= p.t_start AND c.__time < p.t_end AND c.country = 'IND' AND c.status = 200 AND c.tin IS NOT NULL AND c.tin NOT IN ('', 'null') AND c.__time > i.sl_time GROUP BY 1,2,3 ), instance_labeled AS ( SELECT i.month_period || ' 11 to 15' AS month_period, COALESCE(i.os, i.channel) AS saleschannel, i.exp_Variant, i.user_type, CASE WHEN COALESCE(u.sl_Land, 0) = 1 AND COALESCE(u.Price_range, 0) = 1 THEN 'Price Range Tuple' ELSE 'Normal Tuple' END AS tuple_type, i.mri_session_id, i.route_id, i.srp_time, i.sl_time, ns.next_srp_time, ci.custinfo_time, pay.payment_time, conf.confirm_time, COALESCE(conf.tin_count, 0) AS tin_count, CASE WHEN ci.custinfo_time IS NOT NULL AND (ns.next_srp_time IS NULL OR ci.custinfo_time < ns.next_srp_time) THEN 'proceeded' WHEN ns.next_srp_time IS NOT NULL AND (ci.custinfo_time IS NULL OR ns.next_srp_time < ci.custinfo_time) AND (conf.confirm_time IS NULL OR ns.next_srp_time < conf.confirm_time) THEN 'back to SRP' ELSE 'dropped off' END AS user_behaviour FROM sl_instances i LEFT JOIN ui_flags_per_sl u ON u.mri_session_id = i.mri_session_id AND u.route_id = i.route_id AND u.sl_time = i.sl_time LEFT JOIN next_srp_after_sl ns ON ns.mri_session_id = i.mri_session_id AND ns.route_id = i.route_id AND ns.sl_time = i.sl_time LEFT JOIN custinfo_after_sl ci ON ci.mri_session_id = i.mri_session_id AND ci.route_id = i.route_id AND ci.sl_time = i.sl_time LEFT JOIN payment_after_sl pay ON pay.mri_session_id = i.mri_session_id AND pay.route_id = i.route_id AND pay.sl_time = i.sl_time LEFT JOIN confirm_after_sl conf ON conf.mri_session_id = i.mri_session_id AND conf.route_id = i.route_id AND conf.sl_time = i.sl_time ) SELECT month_period, saleschannel, exp_Variant, user_type, tuple_type, user_behaviour, /* instance-wise counts */ COUNT(mri_session_id) AS srpload, COUNT(mri_session_id) AS slload, COUNT(CASE WHEN user_behaviour = 'proceeded' THEN mri_session_id END) AS CustInfoload, COUNT(CASE WHEN user_behaviour = 'proceeded' AND payment_time IS NOT NULL AND (next_srp_time IS NULL OR payment_time < next_srp_time) THEN mri_session_id END) AS paymentload, COUNT(CASE WHEN user_behaviour = 'proceeded' AND confirm_time IS NOT NULL AND (next_srp_time IS NULL OR confirm_time < next_srp_time) THEN mri_session_id END) AS confirmsession, SUM(CASE WHEN user_behaviour = 'proceeded' AND confirm_time IS NOT NULL AND (next_srp_time IS NULL OR confirm_time < next_srp_time) THEN tin_count ELSE 0 END) AS tin FROM instance_labeled GROUP BY 1,2,3,4,5,6 ORDER BY 1,2,3,4,5,6;
